SELECT CASE WHEN duration_sec >= 398 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, DATE_TRUNC('YEAR', event_time) AS year_start, page, SUM(duration_sec) FILTER (WHERE event_type = 'page_view') AS page_view_total_duration_sec, APPROX_PERCENTILE(duration_sec, 0.95) AS duration_sec_p95, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, SUM(duration_sec) AS total_duration_sec, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list, COUNT_IF(event_type = 'click') AS click_events FROM web_events GROUP BY CASE WHEN duration_sec >= 398 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', event_time), page HAVING STDDEV_SAMP(duration_sec) > 0;
